33	#[test]
34	fn manor_skeleton_regenerate_ability() {
35	    let reg = registry();
36	    let mut state = game_at_step(Step::PrecombatMain, P0);
37	
38	    let skeleton = named_creature(&mut state, &reg, "Manor Skeleton", P0);
39	
40	    // Add mana to pay {1}{B} for regenerate.
41	    state.get_player_mut(P0).mana_pool.add(ManaType::Colorless, 1);
42	    state.get_player_mut(P0).mana_pool.add(ManaType::Black, 1);
