// Lantern Spirit — {2}{U} 2/1 Spirit, Flying, {U}: return to hand
// ══════════════════════════════════════════════════════════════════

#[test]
fn lantern_spirit_has_correct_stats() {
    let reg = registry();
    let id = reg.get_id_by_name("Lantern Spirit").unwrap();
    let data = reg.card_data(id).unwrap();
    assert_eq!(data.power, Some(2));
